  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'Amber Permit Rules', 'syllogism'::dm_question_type, 'At a fictional permit office, every amber permit is inspected. No inspected permit is approved automatically. Some amber permits are renewals. Every renewal permit carries a barcode. Decide whether each statement follows from these rules.', NULL, NULL, NULL, NULL, NULL, v_base_order + 1, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'Some renewal permits are inspected.', 'Yes', 'Some renewals are amber, and every amber permit is inspected.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'No amber permit is approved automatically.', 'Yes', 'Every amber permit is inspected, and no inspected permit is approved automatically.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'Every barcoded permit is amber.', 'No', 'The rules say renewals carry barcodes, but do not restrict barcodes to amber permits.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'Some barcoded permits are not approved automatically.', 'Yes', 'The amber renewals exist; each has a barcode and, as an inspected amber permit, is not approved automatically.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('f1d045ff-a3b1-4bd7-9901-d6ed31b84270'::uuid, 'Some inspected permits are amber.', 'Yes', 'The stated amber renewals exist, so at least those amber permits are inspected.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'Tile Workshop Rules', 'syllogism'::dm_question_type, 'In a fictional tile workshop, every glazed tile is kiln-fired. Some kiln-fired tiles are hand-painted. No hand-painted tile is sold loose. Every tile sold loose has a label. Decide whether each statement follows.', NULL, NULL, NULL, NULL, NULL, v_base_order + 2, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'Some kiln-fired tiles are not sold loose.', 'Yes', 'The hand-painted kiln-fired tiles exist and no hand-painted tile is sold loose.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'Every glazed tile is hand-painted.', 'No', 'Glazed tiles are kiln-fired, but kiln firing does not imply hand painting.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'No hand-painted tile is sold loose.', 'Yes', 'This is an explicit rule.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'Some labelled tiles are glazed.', 'No', 'Neither the existence of loose tiles nor a link from loose to glazed is given.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('cac6abc2-93cb-4129-a31d-290ec0279fee'::uuid, 'Some kiln-fired tiles are hand-painted.', 'Yes', 'This is explicitly stated.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'Restricted Archive Files', 'syllogism'::dm_question_type, 'In a fictional archive, every encrypted file is backed up. A file can be backed up only if it is indexed. Some encrypted files are restricted. No restricted file is shared publicly. Decide whether each statement follows.', NULL, NULL, NULL, NULL, NULL, v_base_order + 3, 'hard', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'Some restricted files are indexed.', 'Yes', 'The encrypted restricted files exist. Encrypted files are backed up, and backed-up files must be indexed.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'Every encrypted file is indexed.', 'Yes', 'Encryption implies backup; backup requires indexing.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'No encrypted file is shared publicly.', 'No', 'Only the restricted encrypted files are known to be unshared; other encrypted files could be shared.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'Some backed-up files are restricted.', 'Yes', 'The encrypted restricted files exist and are all backed up.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('7b16280a-94d9-4e5d-9029-9bb35f023170'::uuid, 'Every indexed file is backed up.', 'No', 'Backup requires indexing; the converse is not stated.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('b72ef91a-3680-4f37-aa0f-89998470d7b2'::uuid, 'Display Crate Sequence', 'logic_puzzle'::dm_question_type, 'Five display crates A, B, C, D and E are placed in a row from left to right. A is third. C is immediately to the right of A. B is somewhere to the left of D, and D is somewhere to the left of A. Which crate is first?', NULL, NULL, NULL, 'B', 'A is third and C fourth. B and D must occupy the first two places in that order; E is fifth. B is first.', v_base_order + 4, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b72ef91a-3680-4f37-aa0f-89998470d7b2'::uuid, 'A', 'A', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b72ef91a-3680-4f37-aa0f-89998470d7b2'::uuid, 'B', 'B', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b72ef91a-3680-4f37-aa0f-89998470d7b2'::uuid, 'C', 'D', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b72ef91a-3680-4f37-aa0f-89998470d7b2'::uuid, 'D', 'E', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('2fea6610-f787-41a0-93be-28344a314aeb'::uuid, 'Workshop Station Assignments', 'logic_puzzle'::dm_question_type, 'Four makers, Imani, Joel, Kira and Luca, each use a different station: printing, cutting, painting or packing. Imani does not print or paint. Joel uses the station immediately before packing in the fixed order printing, cutting, painting, packing. Kira does not cut. Luca prints. Which station does Imani use?', NULL, NULL, NULL, 'B', 'Joel paints because painting immediately precedes packing. Luca prints. The remaining stations are cutting and packing; Kira cannot cut, so Kira packs and Imani cuts.', v_base_order + 5, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2fea6610-f787-41a0-93be-28344a314aeb'::uuid, 'A', 'Printing', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2fea6610-f787-41a0-93be-28344a314aeb'::uuid, 'B', 'Cutting', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2fea6610-f787-41a0-93be-28344a314aeb'::uuid, 'C', 'Painting', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('2fea6610-f787-41a0-93be-28344a314aeb'::uuid, 'D', 'Packing', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('d822dd15-d4f7-4911-8187-2b9c6c356d91'::uuid, 'Harbour Launch Slots', 'logic_puzzle'::dm_question_type, 'Five launches named Alder, Birch, Cedar, Dune and Elm leave at 09:00, 09:15, 09:30, 09:45 and 10:00, one per slot. Birch leaves immediately after Alder. Dune leaves after Birch but before Elm. Cedar leaves after Alder but not immediately after Birch. Elm leaves at 10:00. Which launch leaves at 09:30?', NULL, NULL, NULL, 'D', 'Elm is fifth. Dune must be before Elm and after consecutive Alder-Birch. If Alder-Birch occupied slots 1-2, Cedar must follow Alder but cannot be slot 3, so Cedar=4 and Dune=3. If they occupied slots 2-3, Cedar would need slot 4, leaving no slot for Dune before Elm. Therefore Dune is at 09:30.', v_base_order + 6, 'hard', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d822dd15-d4f7-4911-8187-2b9c6c356d91'::uuid, 'A', 'Alder', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d822dd15-d4f7-4911-8187-2b9c6c356d91'::uuid, 'B', 'Birch', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d822dd15-d4f7-4911-8187-2b9c6c356d91'::uuid, 'C', 'Cedar', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('d822dd15-d4f7-4911-8187-2b9c6c356d91'::uuid, 'D', 'Dune', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'Repair Desk Outcomes', 'interpreting_info'::dm_question_type, 'A fictional repair desk recorded items brought in and successfully repaired over two Saturdays. Each item belongs to exactly one category. Decide whether each statement follows from the table.', '{"headers":["Category","First: brought","First: repaired","Second: brought","Second: repaired"],"rows":[["Lamps","18","12","22","17"],["Radios","15","9","19","14"],["Toys","20","15","18","13"]]}'::jsonb, NULL, NULL, NULL, NULL, v_base_order + 7, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'More lamps than radios were brought in across both Saturdays.', 'Yes', 'Lamps: 18+22=40; radios: 15+19=34.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'The total number of successful repairs was higher on the second Saturday.', 'Yes', 'First Saturday: 12+9+15=36. Second: 17+14+13=44.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'Every category had more successful repairs on the second Saturday.', 'No', 'The toy category fell from 15 to 13 successful repairs.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'The repair rate for radios was exactly 60% on the first Saturday.', 'Yes', 'Nine of fifteen radios were repaired: 9/15=60%.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8b01c2cb-8622-4e6a-9b00-42f3a71f7f74'::uuid, 'More toys will be repaired on the third Saturday than on the second.', 'No', 'The table provides no third-Saturday result or valid prediction.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'Shuttle Passenger Record', 'interpreting_info'::dm_question_type, 'A fictional shuttle carried 96 distinct passengers on Monday. Of these, 42 boarded before noon and the remainder boarded later. Thirty passengers travelled with a bicycle; 18 of those boarded before noon. Every passenger boarded exactly once. Decide whether each statement follows.', NULL, NULL, NULL, NULL, NULL, v_base_order + 8, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'Fifty-four passengers boarded after noon.', 'Yes', '96-42=54.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'Twelve passengers with a bicycle boarded after noon.', 'Yes', 'Thirty travelled with a bicycle and 18 boarded before noon, leaving 12 after noon.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'More than half of the before-noon passengers travelled with a bicycle.', 'No', 'Only 18 of 42 did; half of 42 is 21.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'More passengers without a bicycle boarded after noon than before noon.', 'Yes', 'After noon without bicycle: 54-12=42; before noon without bicycle: 42-18=24.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('8383651a-ae22-4096-b8b3-d29328677eff'::uuid, 'At least one passenger who boarded later will bring a bicycle on Tuesday.', 'No', 'Monday data gives no Tuesday behaviour.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'Helpline Transfer Audit', 'interpreting_info'::dm_question_type, 'A fictional helpline reports calls answered at three desks during one shift. Each call is answered by exactly one desk; transferred calls are included in that desk’s answered total and are transferred once. Decide whether each statement follows.', '{"headers":["Desk","Calls answered","Calls transferred"],"rows":[["North","80","20"],["South","120","36"],["East","100","15"]]}'::jsonb, NULL, NULL, NULL, NULL, v_base_order + 9, 'hard', FALSE, TRUE);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'The South desk transferred the largest number of calls.', 'Yes', 'South transferred 36, compared with North 20 and East 15.', 1);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'The North desk transferred one quarter of its answered calls.', 'Yes', '20/80=1/4.', 2);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'The combined transfer rate across all desks was less than one quarter.', 'Yes', 'There were 20+36+15=71 transfers out of 80+120+100=300 calls; 71/300 is about 23.67%.', 3);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'East had a lower transfer rate than South.', 'Yes', 'East: 15/100=15%; South: 36/120=30%.', 4);
  INSERT INTO decision_making_question_statements (question_id, statement_text, correct_answer, answer_reason, order_index) VALUES ('d9aae1fd-d6e2-4408-81ee-7a2c661c6acb'::uuid, 'The South desk answered more calls without transfer than the other two desks combined.', 'No', 'South had 120-36=84; North and East together had (80-20)+(100-15)=145.', 5);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('b0f99a28-6127-40ab-b548-bce5ef933dc2'::uuid, 'Repair Booking Trial', 'recognising_assumptions'::dm_question_type, 'A fictional repair workshop wants to introduce optional online appointment booking to reduce the average waiting time for visitors. Which is the strongest argument?', NULL, NULL, NULL, 'C', 'The six-week comparison directly measures the proposed outcome under comparable staffing and hours. The other arguments concern preference or minor administration rather than average waiting time.', v_base_order + 10, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b0f99a28-6127-40ab-b548-bce5ef933dc2'::uuid, 'A', 'Yes; visitors often prefer to know their appointment time in advance.', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b0f99a28-6127-40ab-b548-bce5ef933dc2'::uuid, 'B', 'No; the workshop’s wall clock would need to be checked more often.', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b0f99a28-6127-40ab-b548-bce5ef933dc2'::uuid, 'C', 'Yes; in a six-week trial with the same staffing and opening hours, mean waiting time fell from 28 to 16 minutes when appointment slots were offered.', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('b0f99a28-6127-40ab-b548-bce5ef933dc2'::uuid, 'D', 'No; some visitors would still prefer to arrive without booking.', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('c2e726ed-8cb5-4d7e-88ba-9a6f1118b8ac'::uuid, 'Early River Shuttle', 'recognising_assumptions'::dm_question_type, 'A fictional town considers adding a 07:00 river shuttle to reduce crowding on its existing 07:30 departure. Which is the strongest argument?', NULL, NULL, NULL, 'C', 'The trial directly shows that the proposed trip did not reduce crowding on the 07:30 service. The other arguments do not measure that outcome.', v_base_order + 11, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c2e726ed-8cb5-4d7e-88ba-9a6f1118b8ac'::uuid, 'A', 'Yes; many residents say an earlier departure would feel convenient.', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c2e726ed-8cb5-4d7e-88ba-9a6f1118b8ac'::uuid, 'B', 'Yes; the extra vessel has attractive new seats.', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c2e726ed-8cb5-4d7e-88ba-9a6f1118b8ac'::uuid, 'C', 'No; a trial of the 07:00 trip drew mostly passengers who had previously travelled after 08:00, while the number aboard the 07:30 trip was unchanged.', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('c2e726ed-8cb5-4d7e-88ba-9a6f1118b8ac'::uuid, 'D', 'No; some passengers dislike travelling before sunrise.', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('fbaf9861-744c-45f3-9879-5fad8c0e62eb'::uuid, 'Archive Catalogue Copies', 'recognising_assumptions'::dm_question_type, 'A fictional archive keeps its only catalogue on paper in one building. Should it scan the catalogue and store duplicate digital copies in two other buildings to reduce the risk of losing all catalogue records if the archive building is damaged? Which is the strongest argument?', NULL, NULL, NULL, 'A', 'Copies in other buildings would remain available if damage destroyed the only paper catalogue, directly reducing the stated risk of total record loss. Convenience, staff preference and a temporary need for electricity do not address permanent loss as directly.', v_base_order + 12, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('fbaf9861-744c-45f3-9879-5fad8c0e62eb'::uuid, 'A', 'Yes; if damage destroys the paper catalogue in the archive building, the copies held elsewhere would preserve its records.', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('fbaf9861-744c-45f3-9879-5fad8c0e62eb'::uuid, 'B', 'Yes; visitors often enjoy using searchable screens.', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('fbaf9861-744c-45f3-9879-5fad8c0e62eb'::uuid, 'C', 'No; some staff prefer reading the original handwritten pages.', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('fbaf9861-744c-45f3-9879-5fad8c0e62eb'::uuid, 'D', 'No; the buildings holding the copies would need electricity to open the files.', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('80fd9429-e35b-42df-8c4a-2e29db932c4e'::uuid, 'Coastal Trail Signs', 'venn_diagram'::dm_question_type, 'A diagram shows 58 signs on a fictional coastal trail. Set A means “mentions birds” and set B means “mentions tides”. Numbers give the number of signs in each exclusive region.
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('80fd9429-e35b-42df-8c4a-2e29db932c4e'::uuid, 'A', '11', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('80fd9429-e35b-42df-8c4a-2e29db932c4e'::uuid, 'B', '13', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('80fd9429-e35b-42df-8c4a-2e29db932c4e'::uuid, 'C', '18', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('80fd9429-e35b-42df-8c4a-2e29db932c4e'::uuid, 'D', '29', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('a10ba3a4-0fa6-488c-ade8-dbf012618322'::uuid, 'Studio Workshop Enrolment', 'venn_diagram'::dm_question_type, 'The diagram classifies 64 fictional studio members by enrolment in clay, print and textile workshops. Each number is the count in that exclusive region.
