  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('45d47239-046a-4ade-98a3-fa3de9802138'::uuid, 'Observatory Alert Channels', 'probabilistic'::dm_question_type, 'At a fictional observatory, two independent alert channels operate on a given night. Channel A sends an alert with probability 0.30; channel B sends an alert with probability 0.20. What is the probability that exactly one channel sends an alert?', NULL, NULL, NULL, 'B', 'Exactly one means A alone or B alone: (0.30×0.80)+(0.70×0.20)=0.24+0.14=0.38.', v_base_order + 17, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('45d47239-046a-4ade-98a3-fa3de9802138'::uuid, 'A', '0.06', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('45d47239-046a-4ade-98a3-fa3de9802138'::uuid, 'B', '0.38', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('45d47239-046a-4ade-98a3-fa3de9802138'::uuid, 'C', '0.44', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('45d47239-046a-4ade-98a3-fa3de9802138'::uuid, 'D', '0.50', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('8efec042-4316-4d7d-a909-7de9beb2433b'::uuid, 'Rehearsal Room Collision', 'probabilistic'::dm_question_type, 'Three performers independently choose one of four rehearsal rooms. Each performer is equally likely to choose any room. What is the probability that at least two performers choose the same room?', NULL, NULL, NULL, 'D', 'Use the complement. For all three performers to choose different rooms, the first can choose any room, the second must choose one of the other three, and the third one of the remaining two: (4/4)×(3/4)×(2/4)=3/8. Therefore the probability that at least two choose the same room is 1−3/8=5/8.', v_base_order + 18, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8efec042-4316-4d7d-a909-7de9beb2433b'::uuid, 'A', '1/4', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8efec042-4316-4d7d-a909-7de9beb2433b'::uuid, 'B', '3/8', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8efec042-4316-4d7d-a909-7de9beb2433b'::uuid, 'C', '1/2', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('8efec042-4316-4d7d-a909-7de9beb2433b'::uuid, 'D', '5/8', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('f5541786-42ff-4db3-9e49-fdf982e875e3'::uuid, 'Ferry Rain Covers', 'probabilistic'::dm_question_type, 'A fictional ferry carried 120 passengers on its morning trip and 80 on its evening trip. On the morning trip, 30 passengers took a rain cover; on the evening trip, 40 did. One of the 200 passengers is chosen uniformly at random. Given that the selected passenger took a rain cover, what is the probability that they travelled in the evening?', NULL, NULL, NULL, 'C', 'Among rain-cover users there were 30+40=70 passengers, of whom 40 travelled in the evening. Conditional probability = 40/70=4/7.', v_base_order + 19, 'hard', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('f5541786-42ff-4db3-9e49-fdf982e875e3'::uuid, 'A', '1/5', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('f5541786-42ff-4db3-9e49-fdf982e875e3'::uuid, 'B', '2/5', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('f5541786-42ff-4db3-9e49-fdf982e875e3'::uuid, 'C', '4/7', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('f5541786-42ff-4db3-9e49-fdf982e875e3'::uuid, 'D', '1/2', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('4c84d495-18b8-4ef5-a86f-1beb34142de1'::uuid, 'Display Volume Order', 'probabilistic'::dm_question_type, 'Six distinct display volumes are arranged in a random order on one shelf. Two named volumes, Atlas and Beacon, are among the six. What is the probability that Atlas and Beacon are next to each other?', NULL, NULL, NULL, 'B', 'Treat Atlas and Beacon as one block. The block and four other volumes have 5! orders, and the two named volumes have 2 internal orders. Thus favourable orders = 2×5!, out of 6! total: 2/6=1/3.', v_base_order + 20, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4c84d495-18b8-4ef5-a86f-1beb34142de1'::uuid, 'A', '1/6', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4c84d495-18b8-4ef5-a86f-1beb34142de1'::uuid, 'B', '1/3', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4c84d495-18b8-4ef5-a86f-1beb34142de1'::uuid, 'C', '2/5', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('4c84d495-18b8-4ef5-a86f-1beb34142de1'::uuid, 'D', '1/2', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('3aa6e000-327c-45d7-b2f5-26142b4b7177'::uuid, 'Community Radio Programme Tags', 'venn_diagram'::dm_question_type, 'A station has 39 programmes. A programme may carry the Music, Talk, or Local tag. Of these, 12 have Music, 18 have Talk, and 11 have Local. Four have both Music and Talk; three have both Talk and Local; none have both Music and Local. Five programmes have none of the three tags. Which diagram represents these data? Each number is the count in that exclusive region.', NULL, NULL, NULL, 'A', 'Because Music and Local never overlap, no programme can have all three tags. Music-only is 12−4=8; Talk-only is 18−4−3=11; Local-only is 11−3=8. With five outside, diagram A matches every count and overlap.', v_base_order + 21, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('3aa6e000-327c-45d7-b2f5-26142b4b7177'::uuid, 'A', '', '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Music","shape":"square"},{"id":"set2","label":"Talk","shape":"oval"},{"id":"set3","label":"Local","shape":"diamond"}],"regions":{"set1_only":8,"set2_only":11,"set3_only":8,"set1_set2":4,"set2_set3":3,"outside":5}}'::jsonb, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('3aa6e000-327c-45d7-b2f5-26142b4b7177'::uuid, 'B', '', '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Music","shape":"square"},{"id":"set2","label":"Talk","shape":"oval"},{"id":"set3","label":"Local","shape":"diamond"}],"regions":{"set1_only":12,"set2_only":18,"set3_only":4,"outside":5}}'::jsonb, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('3aa6e000-327c-45d7-b2f5-26142b4b7177'::uuid, 'C', '', '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Music","shape":"square"},{"id":"set2","label":"Talk","shape":"oval"},{"id":"set3","label":"Local","shape":"diamond"}],"regions":{"set1_only":20,"set1_set2":8,"set1_set3":"0","set1_set2_set3":6,"outside":5}}'::jsonb, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('3aa6e000-327c-45d7-b2f5-26142b4b7177'::uuid, 'D', '', '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Music","shape":"square"},{"id":"set2","label":"Talk","shape":"oval"},{"id":"set3","label":"Local","shape":"diamond"}],"regions":{"set1_only":8,"set2_only":14,"set3_only":8,"set1_set2":4,"outside":5}}'::jsonb, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('5297e7b2-a46d-4750-9a7a-09db32602f59'::uuid, 'Observatory Image Archive', 'venn_diagram'::dm_question_type, 'Every digitised observatory image has been checked, and every published image has been checked. Some checked images are both digitised and published. The diagram uses a rectangle for Checked, a circle for Digitised, and a diamond for Published. Each letter identifies one exclusive region. An image in region Q is compared with an image in region R. Which statement must be true of both images?', NULL, '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Checked","shape":"rectangle"},{"id":"set2","label":"Digitised","shape":"circle"},{"id":"set3","label":"Published","shape":"diamond"}],"regions":{"set1_only":"P","set1_set2":"Q","set1_set3":"T","set1_set2_set3":"R","outside":"S"}}'::jsonb, NULL, 'B', 'Q lies in Checked and Digitised but outside Published. R lies in all three. Both images have therefore been digitised. Only the R image is published, and both have been checked.', v_base_order + 22, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('5297e7b2-a46d-4750-9a7a-09db32602f59'::uuid, 'A', 'Both were published.', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('5297e7b2-a46d-4750-9a7a-09db32602f59'::uuid, 'B', 'Both were digitised.', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('5297e7b2-a46d-4750-9a7a-09db32602f59'::uuid, 'C', 'Neither was checked.', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('5297e7b2-a46d-4750-9a7a-09db32602f59'::uuid, 'D', 'Exactly one was digitised.', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('308bcd28-85d0-4149-a2fd-3f6dd456dfd3'::uuid, 'Repair Fair Route Cards', 'venn_diagram'::dm_question_type, 'At a repair fair, each of 58 visitors completes one route card indicating whether they joined Repair, Reuse, Donate, or Recycle. The diagram shows four different shapes. Each number gives a count in an exclusive region. How many visitors joined at least one of Repair or Donate?', NULL, '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Repair","shape":"horizontal_strip"},{"id":"set2","label":"Reuse","shape":"vertical_strip"},{"id":"set3","label":"Donate","shape":"oval"},{"id":"set4","label":"Recycle","shape":"vertical_oval"}],"regions":{"set1_only":7,"set2_only":9,"set3_only":8,"set4_only":6,"set1_set2":4,"set2_set3":5,"set3_set4":3,"set1_set4":6,"outside":10}}'::jsonb, NULL, 'D', 'Repair and Donate do not overlap, so add every region in either shape: Repair has 7+4+6=17; Donate has 8+5+3=16. The total is 33. The other 25 cards are in Reuse only, Recycle only, or outside.', v_base_order + 23, 'normal', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('308bcd28-85d0-4149-a2fd-3f6dd456dfd3'::uuid, 'A', '24', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('308bcd28-85d0-4149-a2fd-3f6dd456dfd3'::uuid, 'B', '29', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('308bcd28-85d0-4149-a2fd-3f6dd456dfd3'::uuid, 'C', '31', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('308bcd28-85d0-4149-a2fd-3f6dd456dfd3'::uuid, 'D', '33', NULL, NULL, 4);
  INSERT INTO decision_making_questions (id, title, type, stem, table_data, stimulus_diagram, venn_geometry, correct_answer, answer_reason, order_index, difficulty, hide_labels, is_free) VALUES ('7e0c5ab8-a660-4780-a9f1-617433e4056a'::uuid, 'Packaging Lab Fault Codes', 'venn_diagram'::dm_question_type, 'A packaging lab classifies samples by whether they need a retest and whether they have a seal, print, or weight fault. A sample can have at most one of the three named fault types. The diagram gives exclusive-region counts, except that the retest-only region is marked ?. The lab found that the number needing a retest is twice the number not needing one. How many samples are in the ? region?', NULL, '{"diagramLayout":"auto","sets":[{"id":"set1","label":"Retest","shape":"circle"},{"id":"set2","label":"Seal fault","shape":"diamond"},{"id":"set3","label":"Print fault","shape":"vertical_oval"},{"id":"set4","label":"Weight fault","shape":"vertical_oval"}],"regions":{"set1_only":"?","set2_only":5,"set3_only":7,"set4_only":6,"set1_set2":4,"set1_set3":6,"set1_set4":8,"outside":3}}'::jsonb, NULL, 'C', 'Outside Retest there are 5+7+6+3=21 samples. Twice as many need a retest, so Retest contains 42. The three Retest-and-fault regions contain 4+6+8=18, leaving 42−18=24 in the retest-only region.', v_base_order + 24, 'hard', FALSE, TRUE);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('7e0c5ab8-a660-4780-a9f1-617433e4056a'::uuid, 'A', '18', NULL, NULL, 1);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('7e0c5ab8-a660-4780-a9f1-617433e4056a'::uuid, 'B', '21', NULL, NULL, 2);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('7e0c5ab8-a660-4780-a9f1-617433e4056a'::uuid, 'C', '24', NULL, NULL, 3);
  INSERT INTO decision_making_question_options (question_id, label, option_text, option_data, venn_geometry, order_index) VALUES ('7e0c5ab8-a660-4780-a9f1-617433e4056a'::uuid, 'D', '27', NULL, NULL, 4);
